import { createServer, IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import * as crypto from 'crypto';

// Database driver configuration for cross-service auth
interface ServiceEndpoint {
  host: string;
  port: number;
  protocol: string;
}

interface AuthToken {
  service: string;
  nonce: string;
  timestamp: number;
  signature: string;
}

const TRUSTED_SERVICES: Record<string, ServiceEndpoint> = {
  'analytics': { host: 'analytics.internal.corp', port: 443, protocol: 'https' },
  'reporting': { host: 'reporting.internal.corp', port: 443, protocol: 'https' },
  'dashboard': { host: 'dashboard.internal.corp', port: 443, protocol: 'https' },
};

const HMAC_SECRET = process.env.HMAC_SECRET || crypto.randomBytes(32).toString('hex');

function verifyTokenSignature(token: AuthToken): boolean {
  if (typeof token.signature !== 'string') return false;
  const payload = `${token.service}:${token.nonce}:${token.timestamp}`;
  const expected = crypto.createHmac('sha256', HMAC_SECRET).update(payload).digest('hex');
  const expectedBuf = Buffer.from(expected);
  const providedBuf = Buffer.from(token.signature);
  // timingSafeEqual throws on length mismatch; guard against it (attacker-controlled length -> DoS)
  if (expectedBuf.length !== providedBuf.length) return false;
  return crypto.timingSafeEqual(expectedBuf, providedBuf);
}

function isTokenFresh(token: AuthToken, maxAgeMs: number = 300000): boolean {
  return (Date.now() - token.timestamp) < maxAgeMs;
}

// Normalize service identifier to prevent traversal
function normalizeServiceId(raw: string): string {
  return raw.replace(/[^a-zA-Z0-9_-]/g, '').toLowerCase();
}

// Build the redirect URI for cross-service SSO handoff
function buildRedirectUri(serviceId: string, callbackPath: string): string | null {
  const normalized = normalizeServiceId(serviceId);
  const endpoint = TRUSTED_SERVICES[normalized];
  if (!endpoint) return null;

  // Construct base URL from trusted endpoint config
  const baseUrl = `${endpoint.protocol}://${endpoint.host}:${endpoint.port}`;

  // Validate callback is a relative path only - reject anything with protocol or authority
  if (callbackPath.includes('://') || callbackPath.startsWith('//')) {
    return null;
  }

  // Ensure path starts with / and has no encoded separators that could bypass
  const decodedPath = decodeURIComponent(callbackPath);
  if (decodedPath.includes('://') || decodedPath.startsWith('//') || !callbackPath.startsWith('/')) {
    return null;
  }

  // Parse and validate the callback path
  const resolved = new URL(callbackPath, baseUrl);

  // Security check: ensure the resolved URL's origin matches our trusted base
  const trustedOrigin = new URL(baseUrl).origin;
  if (resolved.origin !== trustedOrigin) {
    return null;
  }

  // Additional check: ensure hostname hasn't been manipulated
  if (resolved.hostname !== endpoint.host) {
    return null;
  }

  return resolved.toString();
}

// Database connection state tracker
class ConnectionRegistry {
  private connections: Map<string, { lastSeen: number; redirectCount: number }> = new Map();

  recordRedirect(sessionId: string): boolean {
    const entry = this.connections.get(sessionId) || { lastSeen: 0, redirectCount: 0 };
    entry.redirectCount++;
    entry.lastSeen = Date.now();
    this.connections.set(sessionId, entry);
    // Rate limit: max 10 redirects per session
    return entry.redirectCount <= 10;
  }

  cleanup(): void {
    const now = Date.now();
    for (const [key, val] of this.connections) {
      if (now - val.lastSeen > 600000) this.connections.delete(key);
    }
  }
}

const registry = new ConnectionRegistry();

function handleAuthRedirect(req: IncomingMessage, res: ServerResponse): void {
  const reqUrl = new URL(req.url || '/', `http://${req.headers.host}`);
  const serviceId = reqUrl.searchParams.get('service') || '';
  const callback = reqUrl.searchParams.get('callback') || '/auth/complete';
  const tokenStr = reqUrl.searchParams.get('token') || '';
  const sessionId = reqUrl.searchParams.get('session') || crypto.randomUUID();

  // Rate limiting
  if (!registry.recordRedirect(sessionId)) {
    res.writeHead(429);
    res.end('Too many redirects');
    return;
  }

  // Parse and verify auth token
  let token: AuthToken;
  try {
    token = JSON.parse(Buffer.from(tokenStr, 'base64url').toString());
  } catch {
    res.writeHead(400);
    res.end('Invalid token format');
    return;
  }

  if (!verifyTokenSignature(token)) {
    res.writeHead(403);
    res.end('Invalid token signature');
    return;
  }

  if (!isTokenFresh(token)) {
    res.writeHead(403);
    res.end('Token expired');
    return;
  }

  // Verify token service matches requested service
  if (normalizeServiceId(token.service) !== normalizeServiceId(serviceId)) {
    res.writeHead(403);
    res.end('Token service mismatch');
    return;
  }

  // Build redirect URI
  const redirectUri = buildRedirectUri(serviceId, callback);
  if (!redirectUri) {
    res.writeHead(400);
    res.end('Unknown service or invalid callback');
    return;
  }

  // Append session token to redirect
  const finalUrl = new URL(redirectUri);
  finalUrl.searchParams.set('auth_session', sessionId);
  finalUrl.searchParams.set('ts', String(Date.now()));

  res.writeHead(302, { 'Location': finalUrl.toString() });
  res.end();
}

function handleHealthCheck(_req: IncomingMessage, res: ServerResponse): void {
  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ status: 'healthy', uptime: process.uptime() }));
}

const server = createServer((req, res) => {
  const pathname = new URL(req.url || '/', `http://${req.headers.host}`).pathname;

  switch (pathname) {
    case '/auth/redirect':
      handleAuthRedirect(req, res);
      break;
    case '/health':
      handleHealthCheck(req, res);
      break;
    default:
      res.writeHead(404);
      res.end('Not found');
  }
});

server.listen(3000, () => console.log('Auth service listening on :3000'));

export { buildRedirectUri, normalizeServiceId, verifyTokenSignature, handleAuthRedirect };
